import styled from '@emotion/styled';
import { theme } from 'theme';

interface StyledHeaderContainerProps {
  $showDivider?: boolean;
}

export const StyledHeaderContainer = styled.div<StyledHeaderContainerProps>(
  ({ $showDivider }) => ({
    display: 'flex',
    flexDirection: 'column',
    width: '100%',
    alignItems: 'stretch',
    height: 'min-content',

    ...($showDivider === true && {
      borderRight: '1px solid #14141440',
    }),
  }),
);

interface StyledHeaderTopRowProps {
  $noBorderBottom?: boolean;
}

export const StyledHeaderTopRow = styled.div<StyledHeaderTopRowProps>(
  ({ $noBorderBottom }) => ({
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'space-between',
    width: '100%',
    borderBottom: '1px solid #14141429',

    ...($noBorderBottom === true && {
      borderBottom: 'none',
    }),
  }),
);

export const StyledHeaderLegendsSlot = styled.div({
  display: 'flex',
  alignItems: 'center',
  flexShrink: 0,
  minWidth: 0,
});

export const StyledHeaderTitleContainer = styled.div({
  padding: '18px 16px',
  fontWeight: 'bold',
  fontSize: '16px',
  lineHeight: '16px',
  color: '#141414',
  fontFamily: theme.fonts.heading,
  display: 'flex',
  flexDirection: 'column',
  gap: '4px',
});

export const StyledHeaderSubtitle = styled.div({
  fontWeight: 400,
  fontSize: '12px',
  lineHeight: '12px',
  color: 'rgba(20, 20, 20, 0.56)',
  fontFamily: theme.fonts.paragraph,
});
